	if m.Back != nil {
		k := m.Back.PbModelSize(cached)
		b = pbmodelcodec.AppendTag(b, 1, pbmodelcodec.BytesType)
		b = pbmodelcodec.AppendVarint(b, uint64(k))
		before := len(b)
		b2, err := m.Back.PbModelAppend(b, cached)
		if err != nil {
			return b2, err
		}
		if len(b2)-before != k {
			return nil, &pbmodelcodec.Error{Msg: "size mismatch"}
		}
		b = b2
	}
	if m.N != 0 {
		b = pbmodelcodec.AppendTag(b, 2047, pbmodelcodec.VarintType)
		b = pbmodelcodec.AppendVarint(b, pbmodelcodec.EncodeZigZag(int64(m.N)))
	}
