// protowire.ConsumeFieldValue skips it and kept, its tag re-encoded, in *m's unknown fields
// (decode.go:218-231).
func (m *Other) PbModelDecodeField(b []byte, num uint64, typ uint64, depth uint64) (uint64, bool) {
	if num == 1 && typ == pbmodelcodec.BytesType {
		v, k, ok := pbmodelcodec.ConsumeBytes(b)
		if !ok {
			return 0, false
		}
		if m.Back == nil {
			m.Back = &Kinds{}
		}
		if !m.Back.PbModelDecode(v, depth-1) {
			return 0, false
		}
		return k, true
	}
	if num == 2047 && typ == pbmodelcodec.VarintType {
		v, k, ok := pbmodelcodec.ConsumeVarint(b)
		if !ok {
			return 0, false
		}
		m.N = pbmodelcodec.DecodeZigZag32(v)
		return k, true
	}
	if num == 2048 && typ == pbmodelcodec.BytesType {
		v, k, ok := pbmodelcodec.ConsumeBytes(b)
		if !ok {
			return 0, false
		}
		if !pbmodelcodec.ValidUTF8(v) {
			return 0, false
		}
		m.W = append(m.W, string(v))
		return k, true
	}
	k, ok := pbmodelcodec.SkipField(num, typ, b)
	if !ok {
		return 0, false
	}
	m.unknownFields = pbmodelcodec.AppendTag(m.unknownFields, num, typ)
	m.unknownFields = append(m.unknownFields, b[:k]...)
	return k, true
}

// PbModelIsInit: *m has every required field, and so do the messages it holds (singular,
// repeated elements, nil ones included, and a oneof's), as protobuf-go's
// checkInitializedPointer (internal/impl/checkinit.go:26-95) checks them; a nil m: the type
// has no required field of its own (checkinit.go:30-37).
func (m *Other) PbModelIsInit() bool {
	return true
}

// PbModelMergeFrom merges *src into *m, as protobuf-go's mergePointer
// (internal/impl/merge.go:36-113, the field mergers of merge.go and merge_gen.go): a nil
// m panics, a nil src changes nothing; a set scalar or bytes field is copied (bytes into a
// new non-nil slice), a repeated field appended to (each bytes element copied, each message
// element, a nil one included, merged into a new message), a message field merged into
// (allocated if nil), a oneof's set member copied into a new wrapper (unless m's oneof holds
// one of its type: then into that), src's unknown fields appended to m's.
func (m *Other) PbModelMergeFrom(src *Other) {
	if m == nil {
		panic("invalid value: merging into nil message")
	}
	if src == nil {
		return
	}
	if src.Back != nil {
		if m.Back == nil {
			m.Back = &Kinds{}
		}
		m.Back.PbModelMergeFrom(src.Back)
	}
	if src.N != 0 {
		m.N = src.N
	}
	if src.W != nil {
		m.W = append(m.W, src.W...)
	}
	if len(src.unknownFields) > 0 {
		m.unknownFields = append(m.unknownFields, src.unknownFields...)
	}
}

// PbModelUnmarshal is proto.Unmarshal(b, m): *m reset (the generated Reset, `*m = Other{}`,
// a nil m panicking: proto/decode.go:95, reset.go:17-19), b decoded into it with the
// recursion limit 10000 (proto/decode.go:62), then its required fields checked
// (proto/decode.go:132-135).
func (m *Other) PbModelUnmarshal(b []byte) error {
	*m = Other{}
	if !m.PbModelDecode(b, pbmodelcodec.DefaultRecursionLimit) {
		return &pbmodelcodec.Error{Msg: "cannot parse invalid wire-format data"}
	}
	return nil
}

// PbModelClone is proto.Clone(m) (proto/merge.go:41-60): m itself if nil (a typed nil),
// else a new message with *m merged into it (the size cache not copied).
func (m *Other) PbModelClone() interface{} {
	if m == nil {
		return m
	}
	c := &Other{}
	c.PbModelMergeFrom(m)
	return c
}

// PbModelIsNil: m is nil (proto.Marshal's emptyBytesForMessage, proto/encode.go:141-146:
// a nil *T is not a valid message).
func (m *Other) PbModelIsNil() bool {
	return m == nil
}

// PbModelReset is proto.Reset(m) (proto/reset.go:16-22): protoc-gen-go's generated Reset,
// `*m = Other{}` (a nil m panicking, a nil dereference), the size cache and unknown fields
// included; what it stores besides (the message state's MessageInfo, internal/impl) is not
// a field of the model.
func (m *Other) PbModelReset() {
	*m = Other{}
}

// PbModelSelf: m, as proto.Merge's source (a type embedding this one promotes it, as it
// promotes ProtoReflect: the model then merges from the embedded message, as protobuf-go).
func (m *Other) PbModelSelf() interface{} {
	return m
}

// PbModelMerge is proto.Merge(m, src) (proto/merge.go:25-37, then mergeMessage's
// internal/impl merge, merge.go:23-34) for src another message's PbModelSelf: false, and
// nothing changed, if src is not a *Other (protobuf-go panics there, a descriptor mismatch;
// the model does not model it), else m.PbModelMergeFrom(src) (a nil m panics, a nil src
// changes nothing).
func (m *Other) PbModelMerge(src interface{}) bool {
	o, ok := src.(*Other)
	if !ok {
		return false
	}
	m.PbModelMergeFrom(o)
	return true
}
